import audit_trail, workflow_executor, system_triggered_transition
import custom_action_execution, form_render_submit, reporting_engine, stage_approval_gate
import stage_history, stock_ledger, record_cloning, ledger_balancing, document_generation


class Handler(BaseHTTPRequestHandler):
    def base_url(self):
        return f"http://{self.headers.get('Host', 'localhost')}"

    def _body(self):
        length = int(self.headers.get("Content-Length", 0) or 0)
        if not length:
            return {}
        try:
            return json.loads(self.rfile.read(length))
        except Exception:
            return {}

    def do_GET(self):
        self._guarded(self._do_GET)

    def do_POST(self):
        self._guarded(self._do_POST)

    def do_PUT(self):
        self._guarded(self._do_PUT)

    def do_DELETE(self):
        self._guarded(self._do_DELETE)

    def _guarded(self, handler):
        # No route handler here may crash the request thread on a real
        # failure (a broken database file, a bad value from the client) --
        # found by exactly that happening once: an uncaught exception left
        # the client with a reset connection instead of a real 500, and the
        # traceback printed to stderr instead of anywhere a caller could see
        # it. respond() may itself have already sent a partial response by
        # the time something fails downstream of it, so this is a backstop,
        # not the primary error path for handlers that build their own
        # responses.
        try:
            handler()
        except Exception as exc:
            try:
                respond(self, 500, {"error": str(exc)})
            except Exception:
                pass  # headers already sent; nothing more this response can do

    def _do_GET(self):
        parsed = urlparse(self.path)
        path, qs = parsed.path, parse_qs(parsed.query)
        if path == "/" or path == "":
            path = "/index.html"
        if path == "/favicon.ico":
            # Browsers request this unconditionally; a plain 404 shows up as a
            # console error on every single page load with nothing to fix.
            self.send_response(204)
            self.end_headers()
            return
        if path.startswith("/static/") or re.match(r"^/[\w.-]+\.html$", path):
            self._serve_static(path.lstrip("/"))
            return
        if path.startswith("/documents/"):
            self._serve_document(path[len("/documents/"):])
            return
        if path == '/api/contacts':
            self.list_contacts(); return
        if path.startswith('/api/contacts/'):
            self.get_contacts(path[len('/api/contacts/'):]); return
        if path.startswith('/api/history/contacts/'):
            self.history_contacts(path[len('/api/history/contacts/'):]); return
        if path == '/api/invoices':
            self.list_invoices(); return
        if path.startswith('/api/invoices/'):
            self.get_invoices(path[len('/api/invoices/'):]); return
        if path.startswith('/api/history/invoices/'):
            self.history_invoices(path[len('/api/history/invoices/'):]); return
        if path == '/api/invoice_lines':
            self.list_invoice_lines(); return
        if path.startswith('/api/invoice_lines/'):
            self.get_invoice_lines(path[len('/api/invoice_lines/'):]); return
        if path.startswith('/api/history/invoice_lines/'):
            self.history_invoice_lines(path[len('/api/history/invoice_lines/'):]); return
        if path == '/api/bills':
            self.list_bills(); return
        if path.startswith('/api/bills/'):
            self.get_bills(path[len('/api/bills/'):]); return
        if path.startswith('/api/history/bills/'):
            self.history_bills(path[len('/api/history/bills/'):]); return
        if path == '/api/payments':
            self.list_payments(); return
        if path.startswith('/api/payments/'):
            self.get_payments(path[len('/api/payments/'):]); return
        if path.startswith('/api/history/payments/'):
            self.history_payments(path[len('/api/history/payments/'):]); return
        if path.startswith('/api/approvals/invoices/'):
            self.approval_status_invoices(path[len('/api/approvals/invoices/'):]); return

        respond(self, 404, {"error": "no route"})

    def _do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path == '/api/contacts':
            self.create_contacts(self._body()); return
        if path == '/api/invoices':
            self.create_invoices(self._body()); return
        if path == '/api/invoice_lines':
            self.create_invoice_lines(self._body()); return
        if path == '/api/bills':
            self.create_bills(self._body()); return
        if path == '/api/payments':
            self.create_payments(self._body()); return
        if path.startswith('/api/events/invoices/'):
            self.event_invoices(path[len('/api/events/invoices/'):], self._body()); return
        if path.startswith('/api/moves/invoices/'):
            self.move_invoices(path[len('/api/moves/invoices/'):], self._body()); return
        if path.startswith('/api/approvals/invoices/'):
            self.approve_invoices(path[len('/api/approvals/invoices/'):], self._body()); return
        if path.startswith('/api/events/bills/'):
            self.event_bills(path[len('/api/events/bills/'):], self._body()); return
        if path.startswith('/api/moves/bills/'):
            self.move_bills(path[len('/api/moves/bills/'):], self._body()); return
        if path.startswith('/api/actions/invoices/'):
            self.action_invoices(path[len('/api/actions/invoices/'):], self._body()); return

        respond(self, 404, {"error": "no route"})

    def _do_PUT(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path.startswith('/api/contacts/'):
            self.update_contacts(path[len('/api/contacts/'):], self._body()); return
        if path.startswith('/api/invoices/'):
            self.update_invoices(path[len('/api/invoices/'):], self._body()); return
        if path.startswith('/api/invoice_lines/'):
            self.update_invoice_lines(path[len('/api/invoice_lines/'):], self._body()); return
        if path.startswith('/api/bills/'):
            self.update_bills(path[len('/api/bills/'):], self._body()); return
        if path.startswith('/api/payments/'):
            self.update_payments(path[len('/api/payments/'):], self._body()); return

        respond(self, 404, {"error": "no route"})

    def _do_DELETE(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path.startswith('/api/contacts/'):
            self.delete_contacts(path[len('/api/contacts/'):]); return
        if path.startswith('/api/invoice_lines/'):
            self.delete_invoice_lines(path[len('/api/invoice_lines/'):]); return

        respond(self, 404, {"error": "no route"})

    def _serve_static(self, rel):
        rel = rel[len("static/"):] if rel.startswith("static/") else rel
        fp = os.path.join(STATIC_DIR, rel)
        if not os.path.abspath(fp).startswith(os.path.abspath(STATIC_DIR)) or not os.path.isfile(fp):
            respond(self, 404, {"error": "not found"}); return
        with open(fp, "rb") as f:
            body = f.read()
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _serve_document(self, rel):
        doc_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "documents")
        fp = os.path.join(doc_dir, rel)
        if not os.path.abspath(fp).startswith(os.path.abspath(doc_dir)) or not os.path.isfile(fp):
            respond(self, 404, {"error": "not found"}); return
        with open(fp, "rb") as f:
            body = f.read()
        self.send_response(200)
        self.send_header("Content-Type", "application/pdf" if fp.endswith(".pdf") else "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def list_contacts(self):
        rows = query("SELECT * FROM contacts ORDER BY created_at DESC")
        respond(self, 200, rows)

    def get_contacts(self, record_id):
        rows = query("SELECT * FROM contacts WHERE id = ?", (record_id,))
        if not rows:
            respond(self, 404, {"error": "not found"}); return
        respond(self, 200, rows[0])

    def history_contacts(self, row_id):
        """The row's own real trail, oldest first."""
        conn = get_db()
        try:
            trail = audit_trail.history_for(conn, "contacts", row_id)
            stages = [dict(r) for r in conn.execute(
                "SELECT stage, entered_at FROM _stage_history WHERE record_table = ? AND row_id = ? ORDER BY entered_at",
                ("contacts", str(row_id))).fetchall()]
            respond(self, 200, {"audit": trail, "stages": stages})
        finally:
            conn.close()

    def create_contacts(self, body):
        rid = new_id(); now = now_iso()
        values = [rid, now, now, body.get('Name'), body.get('Email'), body.get('Phone'), body.get('Type'), body.get('Payment terms days')]
        execute("INSERT INTO contacts ([id], [created_at], [updated_at], [name], [email], [phone], [type], [payment_terms_days]) VALUES (?, ?, ?, ?, ?, ?, ?, ?)", values)
        effects = []
        respond(self, 201, {"id": rid, "effects": effects})

    def update_contacts(self, record_id, body):
        values = [body.get('Name'), body.get('Email'), body.get('Phone'), body.get('Type'), body.get('Payment terms days'), now_iso(), record_id]
        n = execute("UPDATE contacts SET [name] = ?, [email] = ?, [phone] = ?, [type] = ?, [payment_terms_days] = ?, updated_at = ? WHERE id = ?", values)
        if not n:
            respond(self, 404, {"error": "not found"}); return
        respond(self, 200, {"id": record_id})

    def delete_contacts(self, record_id):
        n = execute("DELETE FROM contacts WHERE id = ?", (record_id,))
        respond(self, 200 if n else 404, {"deleted": bool(n)})

