    def event_invoices(self, row_id, body):
        """A declared automatic edge, fired by the system's own event."""
        transitions = [{"from": "Draft", "to": "Awaiting approval", "mover": "roles", "roles": ["Accountant"]}, {"from": "Awaiting approval", "to": "Awaiting payment", "mover": "roles", "roles": ["Admin"]}, {"from": "Awaiting payment", "to": "Paid", "mover": "automatic", "event": "Payments applied to the invoice reach its total"}, {"from": "Awaiting payment", "to": "Voided", "mover": "roles", "roles": ["Admin"]}, {"from": "Draft", "to": "Voided", "mover": "roles", "roles": ["Accountant"]}]
        approvals = [{"stage": "Awaiting approval", "approvers": ["Admin"]}]
        conn = get_db()
        try:
            row = conn.execute("SELECT stage FROM invoices WHERE id = ?", (row_id,)).fetchone()
            if row is None:
                return respond(self, 404, {"error": "no such row"})
            try:
                stage_approval_gate.check_may_leave(conn, approvals, "invoices", row_id, row["stage"])
            except stage_approval_gate.NotApproved as err:
                return respond(self, 409, {"error": str(err), "waiting_for_approval": True})
            try:
                moved_from, moved_to = system_triggered_transition.fire(
                    conn, "invoices", row_id, "stage", transitions, body.get("event"))
            except system_triggered_transition.NoSuchEvent as err:
                return respond(self, 400, {"error": str(err)})
            except system_triggered_transition.IllegalTransition as err:
                return respond(self, 409, {"error": str(err)})
            stage_history.record_transition(conn, "invoices", row_id, moved_to)
            done = run_transition_effects(conn, [], "invoices", row_id, moved_to)
            respond(self, 200, {"from": moved_from, "to": moved_to, "effects": done})
        finally:
            conn.close()

